/*
 * SMTT CIF - Exportação local para gráfica (1.17.16)
 * PDF CMYK calibrado por ICC 600 DPI, sangria refletida de 1 mm e marcas de corte FORA da arte.
 * Não envia fotografias, CPF, QR Code ou outras informações para serviços externos.
 * Conversão sRGB -> CMYK com tabela gerada pelo perfil ICC SWOP e perfil incorporado.
 * Verde institucional calibrado para evitar o azul da conversão matemática antiga.
 * Para correspondência exata, a gráfica deve informar seu próprio perfil ICC e aprovar a prova.
 */
(function () {
    'use strict';

    var DPI = 600;
    var TRIM_W_MM = 85.60;
    var TRIM_H_MM = 53.98;
    var BLEED_MM = 1;
    var SLUG_MM = 3; // Área externa (papel) para marcas de corte; não faz parte da carteira.
    var PX_PER_MM = DPI / 25.4;
    var W = Math.round((TRIM_W_MM + 2 * BLEED_MM) * PX_PER_MM);
    var H = Math.round((TRIM_H_MM + 2 * BLEED_MM) * PX_PER_MM);
    var B = BLEED_MM * PX_PER_MM;
    var TW = TRIM_W_MM * PX_PER_MM;
    var TH = TRIM_H_MM * PX_PER_MM;
    var encoder = new TextEncoder();
    // Perfil ICC de saída: Artifex CMYK SWOP (distribuído pelo Ghostscript).
    // Tabela RGB->CMYK gerada offline com LittleCMS, 33 pontos por canal.
    // Tudo embutido no plugin: nenhum CPF/fotografia é enviado a terceiros.
    var PROFILE_B64 = '';
    var LUT_B64 = '';
    var cachedLut = null;
    var cachedProfile = null;
    function fromBase64(text) {
        var raw = atob(text), out = new Uint8Array(raw.length);
        for (var i = 0; i < raw.length; i++) { out[i] = raw.charCodeAt(i); }
        return out;
    }
    function getLut() { return cachedLut || (cachedLut = fromBase64(LUT_B64)); }
    function getProfile() { return cachedProfile || (cachedProfile = fromBase64(PROFILE_B64)); }
    function clamp(value) { return Math.min(1, Math.max(0, value)); }

    function ensureImage(img) {
        if (!img) { return Promise.reject(new Error('Imagem obrigatória ausente.')); }
        if (img.complete && img.naturalWidth > 0) { return Promise.resolve(); }
        return new Promise(function (resolve, reject) {
            var timer = setTimeout(function () {
                cleanup(); reject(new Error('Tempo esgotado ao carregar as imagens da CIF.'));
            }, 20000);
            function cleanup() { clearTimeout(timer); img.removeEventListener('load', loaded); img.removeEventListener('error', failed); }
            function loaded() { cleanup(); resolve(); }
            function failed() { cleanup(); reject(new Error('Falha ao carregar uma imagem da CIF.')); }
            img.addEventListener('load', loaded); img.addEventListener('error', failed);
        });
    }

    function rectRelative(el, sheet, scale) {
        var a = el.getBoundingClientRect();
        var b = sheet.getBoundingClientRect();
        return { x: B + (a.left - b.left) * scale, y: B + (a.top - b.top) * scale,
            w: a.width * scale, h: a.height * scale };
    }

    // Sangria verdadeira: a arte ocupa o tamanho de corte CR80 e apenas as suas
    // bordas são prolongadas para fora. A reflexão de uma faixa de ~1 mm evita
    // listras artificiais produzidas pelo esticamento de uma única coluna/linha.
    // Fotografias, textos, assinaturas e QR continuam exclusivamente dentro do corte.
    function paintBleed(ctx, img) {
        var iw = img.naturalWidth, ih = img.naturalHeight;
        var sw = Math.max(1, Math.min(iw, iw * BLEED_MM / TRIM_W_MM));
        var sh = Math.max(1, Math.min(ih, ih * BLEED_MM / TRIM_H_MM));
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(img, B, B, TW, TH);
        function mirror(dx, dy, sourceX, sourceY, sourceW, sourceH, destX, destY, destW, destH) {
            ctx.save();
            ctx.translate(dx, dy);
            ctx.scale(sourceW < 0 ? -1 : 1, sourceH < 0 ? -1 : 1);
            ctx.drawImage(img, sourceX, sourceY, Math.abs(sourceW), Math.abs(sourceH), destX, destY, destW, destH);
            ctx.restore();
        }
        // Faixas laterais, da parte superior e inferior.
        mirror(B, 0, 0, 0, -sw, ih, 0, B, B, TH);
        mirror(B + TW, 0, iw - sw, 0, -sw, ih, -B, B, B, TH);
        mirror(0, B, 0, 0, iw, -sh, B, 0, TW, B);
        mirror(0, B + TH, 0, ih - sh, iw, -sh, B, -B, TW, B);
        // Cantos: reflexão nos dois eixos para continuidade do fundo.
        mirror(B, B, 0, 0, -sw, -sh, 0, 0, B, B);
        mirror(B + TW, B, iw - sw, 0, -sw, -sh, -B, 0, B, B);
        mirror(B, B + TH, 0, ih - sh, -sw, -sh, 0, -B, B, B);
        mirror(B + TW, B + TH, iw - sw, ih - sh, -sw, -sh, -B, -B, B, B);
    }

    function pathRoundRect(ctx, x, y, w, h, radius) {
        var r = Math.max(0, Math.min(radius, w / 2, h / 2));
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + w - r, y);
        ctx.quadraticCurveTo(x + w, y, x + w, y + r);
        ctx.lineTo(x + w, y + h - r);
        ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
        ctx.lineTo(x + r, y + h);
        ctx.quadraticCurveTo(x, y + h, x, y + h - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
    }

    function paintImg(ctx, img, rect, mode, radius, multiply) {
        var iw = img.naturalWidth, ih = img.naturalHeight;
        if (!iw || !ih) { throw new Error('Imagem sem resolução para produção gráfica.'); }
        var s = mode === 'cover' ? Math.max(rect.w / iw, rect.h / ih) : Math.min(rect.w / iw, rect.h / ih);
        var w = iw * s, h = ih * s;
        ctx.save();
        if (radius > 0) { pathRoundRect(ctx, rect.x, rect.y, rect.w, rect.h, radius); ctx.clip(); }
        if (multiply) { ctx.globalCompositeOperation = 'multiply'; }
        ctx.drawImage(img, rect.x + (rect.w - w) / 2, rect.y + (rect.h - h) / 2, w, h);
        ctx.restore();
    }

    function paintText(ctx, el, rect, scale) {
        var txt = (el.textContent || '').trim();
        if (!txt) { return; }
        var style = window.getComputedStyle(el);
        var fs = parseFloat(style.fontSize) * scale;
        var fontWeight = style.fontWeight || '400';
        var family = 'Arial, Helvetica, sans-serif';
        var paddingL = parseFloat(style.paddingLeft || '0') * scale;
        var paddingR = parseFloat(style.paddingRight || '0') * scale;
        var paddingT = parseFloat(style.paddingTop || '0') * scale;
        var max = Math.max(1, rect.w - paddingL - paddingR);
        ctx.save();
        ctx.fillStyle = style.color || '#171b1d';
        ctx.font = fontWeight + ' ' + fs + 'px ' + family;
        ctx.beginPath(); ctx.rect(rect.x, rect.y, rect.w, rect.h); ctx.clip();
        var x = rect.x + paddingL;
        var center = style.justifyContent === 'center' || style.textAlign === 'center';
        if (center) { ctx.textAlign = 'center'; x = rect.x + rect.w / 2; }
        else { ctx.textAlign = 'left'; }
        var multi = style.whiteSpace === 'normal';
        if (multi) {
            var words = txt.split(/\s+/), lines = [], line = '';
            words.forEach(function (word) {
                var trial = line ? line + ' ' + word : word;
                if (line && ctx.measureText(trial).width > max) { lines.push(line); line = word; }
                else { line = trial; }
            });
            if (line) { lines.push(line); }
            var lh = style.lineHeight !== 'normal' ? parseFloat(style.lineHeight) * scale : fs * 1.05;
            ctx.textBaseline = 'top';
            lines.slice(0, Math.max(1, Math.floor((rect.h - paddingT) / lh))).forEach(function (value, i) {
                ctx.fillText(value, x, rect.y + paddingT + i * lh, max);
            });
        } else {
            ctx.textBaseline = 'middle';
            ctx.fillText(txt, x, rect.y + rect.h / 2, max);
        }
        ctx.restore();
    }

    // QR desenhado diretamente dos módulos, sem SVG externo ou reamostragem.
    // Mantém a mesma matriz e quiet zone da visualização do plugin.
    function paintQr(ctx, el, sheet, scale, rect) {
        if (!window.SmttQr || typeof window.SmttQr.matrix !== 'function') {
            throw new Error('Componente do QR Code indisponível.');
        }
        var svg = el.querySelector('svg');
        if (!svg) { throw new Error('QR Code não foi carregado. Aguarde e tente novamente.'); }
        var url = el.getAttribute('data-url');
        if (!url) { throw new Error('QR Code sem URL de validação.'); }
        var modules = window.SmttQr.matrix(url, 'M');
        var quiet = 2, count = modules.length + quiet * 2;
        var inner = rectRelative(svg, sheet, scale);
        var unit = inner.w / count;
        ctx.fillStyle = '#fff'; ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
        ctx.fillStyle = '#000';
        for (var y = 0; y < modules.length; y++) {
            for (var x = 0; x < modules[y].length; x++) {
                if (!modules[y][x]) { continue; }
                var l = Math.round(inner.x + (x + quiet) * unit);
                var t = Math.round(inner.y + (y + quiet) * unit);
                var r = Math.round(inner.x + (x + quiet + 1) * unit);
                var b = Math.round(inner.y + (y + quiet + 1) * unit);
                ctx.fillRect(l, t, Math.max(1, r - l), Math.max(1, b - t));
            }
        }
    }

    async function paintSheet(sheet) {
        var r = sheet.getBoundingClientRect();
        if (!r.width || !r.height) { throw new Error('Visualização da CIF não está pronta.'); }
        var scale = TW / r.width;
        var canvas = document.createElement('canvas');
        canvas.width = W; canvas.height = H;
        var ctx = canvas.getContext('2d', { alpha: false, willReadFrequently: true, colorSpace: 'srgb' });
        if (!ctx) { throw new Error('Navegador não suporta exportação de imagem da CIF.'); }
        ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, W, H);
        var bg = sheet.querySelector('.card-bg');
        await ensureImage(bg);
        paintBleed(ctx, bg);
        var layers = sheet.querySelectorAll('.layer');
        for (var i = 0; i < layers.length; i++) {
            var el = layers[i];
            var rect = rectRelative(el, sheet, scale);
            if (el.tagName.toLowerCase() === 'img') {
                await ensureImage(el);
                var cs = getComputedStyle(el);
                var radius = parseFloat(cs.borderTopLeftRadius || '0') * scale;
                paintImg(ctx, el, rect, cs.objectFit === 'cover' ? 'cover' : 'contain', radius,
                    cs.mixBlendMode === 'multiply');
            } else if (el.classList.contains('qrbox')) {
                paintQr(ctx, el, sheet, scale, rect);
            } else {
                paintText(ctx, el, rect, scale);
            }
        }
        return ctx.getImageData(0, 0, W, H);
    }

    // Conversão de cor controlada: tabela ICC/LittleCMS em tetraedros, sem
    // alteração dos dados pessoais e mantendo ciano, magenta, amarelo e preto.
    // O ajuste seletivo restaura o verde-escuro institucional: no RGB (0,40,34),
    // aproximamos CMYK (90,57,71,72) em vez de (100,0,13,85) azulado.
    function toCMYK(data) {
        var rgba = data.data, lut = getLut();
        var output = new Uint8Array(data.width * data.height * 4);
        var STEPS = 32, RSTEP = 33 * 33 * 4, GSTEP = 33 * 4, BSTEP = 4;
        for (var i = 0; i < rgba.length; i += 4) {
            var red = rgba[i], green = rgba[i + 1], blue = rgba[i + 2];
            var sr = red * STEPS / 255, sg = green * STEPS / 255, sb = blue * STEPS / 255;
            var ri = Math.min(31, Math.floor(sr)), gi = Math.min(31, Math.floor(sg));
            var bi = Math.min(31, Math.floor(sb));
            var fr = sr - ri, fg = sg - gi, fb = sb - bi;
            var first, second, last = RSTEP + GSTEP + BSTEP;
            var high, mid, low;
            if (fr >= fg) {
                if (fg >= fb) { first = RSTEP; second = RSTEP + GSTEP; high = fr; mid = fg; low = fb; }
                else if (fr >= fb) { first = RSTEP; second = RSTEP + BSTEP; high = fr; mid = fb; low = fg; }
                else { first = BSTEP; second = RSTEP + BSTEP; high = fb; mid = fr; low = fg; }
            } else {
                if (fr >= fb) { first = GSTEP; second = GSTEP + RSTEP; high = fg; mid = fr; low = fb; }
                else if (fg >= fb) { first = GSTEP; second = GSTEP + BSTEP; high = fg; mid = fb; low = fr; }
                else { first = BSTEP; second = BSTEP + GSTEP; high = fb; mid = fg; low = fr; }
            }
            var idx = ((ri * 33 + gi) * 33 + bi) * 4;
            var w0 = 1 - high, w1 = high - mid, w2 = mid - low, w3 = low;
            // Transição suave exclusivamente para a área verde-escura.
            // Não altera peles, textos neutros, QR Code nem cores do brasão.
            var greenMask = clamp((green - red - 5) / 20) * clamp((green - blue + 3) / 9) *
                clamp((160 - green) / 70) * clamp((140 - red) / 85) * clamp((green - red) / 35);
            var corrections = [24, -5, 6, -28];
            for (var c = 0; c < 4; c++) {
                var value = lut[idx + c] * w0 + lut[idx + first + c] * w1 +
                    lut[idx + second + c] * w2 + lut[idx + last + c] * w3;
                output[i + c] = Math.round(Math.max(0, Math.min(255, value + greenMask * corrections[c])));
            }
        }
        return output;
    }

    async function compress(bytes) {
        if (typeof CompressionStream !== 'function') { return { bytes: bytes, filter: '' }; }
        var stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream('deflate'));
        return { bytes: new Uint8Array(await new Response(stream).arrayBuffer()), filter: '/Filter /FlateDecode ' };
    }

    // O PDF tem uma área externa branca de 3 mm para marcas de corte (slug).
    // A arte colorida tem 1 mm de sangria real em cada lado. As marcas ficam
    // inteiramente FORA da BleedBox: jamais aparecerão no cartão acabado.
    function makePdf(front, back) {
        var chunks = [], length = 0, offsets = [0];
        function addBytes(bytes) { chunks.push(bytes); length += bytes.length; }
        function addText(s) { addBytes(encoder.encode(s)); }
        function obj(id, body) { offsets[id] = length; addText(id + ' 0 obj\n' + body + '\nendobj\n'); }
        function streamObj(id, dict, bytes) {
            offsets[id] = length;
            addText(id + ' 0 obj\n<< ' + dict + ' /Length ' + bytes.length + ' >>\nstream\n');
            addBytes(bytes); addText('\nendstream\nendobj\n');
        }
        var factor = 72 / 25.4;
        var n = function (value) { return value.toFixed(5); };
        var bleedWidth = (TRIM_W_MM + BLEED_MM * 2) * factor;
        var bleedHeight = (TRIM_H_MM + BLEED_MM * 2) * factor;
        var slug = SLUG_MM * factor;
        var mediaWidth = bleedWidth + 2 * slug;
        var mediaHeight = bleedHeight + 2 * slug;
        var trimLeft = (SLUG_MM + BLEED_MM) * factor;
        var trimBottom = trimLeft;
        var trimRight = trimLeft + TRIM_W_MM * factor;
        var trimTop = trimBottom + TRIM_H_MM * factor;
        var media = '[0 0 ' + n(mediaWidth) + ' ' + n(mediaHeight) + ']';
        var bleedBox = '[' + n(slug) + ' ' + n(slug) + ' ' + n(slug + bleedWidth) + ' ' + n(slug + bleedHeight) + ']';
        var trimBox = '[' + n(trimLeft) + ' ' + n(trimBottom) + ' ' + n(trimRight) + ' ' + n(trimTop) + ']';

        // Marcas padrão de corte 100% K. Distância de segurança de 0,5 mm
        // da arte, com segmentos de 1,8 mm no espaço externo ao cartão.
        var markStart = 0.5 * factor;
        var markEnd = (SLUG_MM - 0.5) * factor;
        var marks = ['q', '0 0 0 1 K', n(0.15 * factor) + ' w'];
        function line(x1, y1, x2, y2) {
            marks.push(n(x1) + ' ' + n(y1) + ' m ' + n(x2) + ' ' + n(y2) + ' l S');
        }
        [trimLeft, trimRight].forEach(function (x) {
            line(x, markStart, x, markEnd);
            line(x, mediaHeight - markEnd, x, mediaHeight - markStart);
        });
        [trimBottom, trimTop].forEach(function (y) {
            line(markStart, y, markEnd, y);
            line(mediaWidth - markEnd, y, mediaWidth - markStart, y);
        });
        marks.push('Q');
        var marksStream = marks.join('\n') + '\n';
        function content(imageKey) {
            return encoder.encode('q\n' + n(bleedWidth) + ' 0 0 ' + n(bleedHeight) + ' ' +
                n(slug) + ' ' + n(slug) + ' cm\n/' + imageKey + ' Do\nQ\n' + marksStream);
        }
        addText('%PDF-1.6\n%SMTT-CIF-CMYK-ICC\n');
        obj(1, '<< /Type /Catalog /Pages 2 0 R /ViewerPreferences << /PrintScaling /None >> >>');
        obj(2, '<< /Type /Pages /Kids [5 0 R 8 0 R] /Count 2 >>');
        var imageDict = function (image) {
            return '/Type /XObject /Subtype /Image /Width ' + W + ' /Height ' + H +
                ' /ColorSpace [/ICCBased 9 0 R] /BitsPerComponent 8 ' + image.filter;
        };
        streamObj(3, imageDict(front), front.bytes);
        streamObj(4, '', content('Im0'));
        obj(5, '<< /Type /Page /Parent 2 0 R /MediaBox ' + media + ' /CropBox ' + media +
            ' /BleedBox ' + bleedBox + ' /TrimBox ' + trimBox +
            ' /Resources << /XObject << /Im0 3 0 R >> >> /Contents 4 0 R >>');
        streamObj(6, imageDict(back), back.bytes);
        streamObj(7, '', content('Im0'));
        obj(8, '<< /Type /Page /Parent 2 0 R /MediaBox ' + media + ' /CropBox ' + media +
            ' /BleedBox ' + bleedBox + ' /TrimBox ' + trimBox +
            ' /Resources << /XObject << /Im0 6 0 R >> >> /Contents 7 0 R >>');
        streamObj(9, '/N 4 /Alternate /DeviceCMYK', getProfile());
        var xref = length;
        addText('xref\n0 10\n0000000000 65535 f \n');
        for (var id = 1; id <= 9; id++) {
            addText(String(offsets[id]).padStart(10, '0') + ' 00000 n \n');
        }
        addText('trailer\n<< /Size 10 /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF\n');
        return new Blob(chunks, { type: 'application/pdf' });
    }

    function safeFilename() {
        var code = (document.querySelector('.back-code') || {}).textContent || 'CARTEIRA';
        return 'CIF-' + code.replace(/[^a-z0-9_-]/ig, '').substring(0, 50) + '-GRAFICA-CMYK-VERDE-ICC-CORTE-1MM.pdf';
    }

    async function exportPdf(button, status) {
        button.disabled = true;
        var old = button.textContent;
        try {
            status.textContent = 'Preparando frente e verso em 600 DPI…';
            if (document.fonts && document.fonts.ready) { await document.fonts.ready; }
            var sheets = document.querySelectorAll('section.sheet');
            if (sheets.length !== 2) { throw new Error('As duas faces da carteira não foram encontradas.'); }
            var images = [];
            for (var i = 0; i < sheets.length; i++) {
                var rgba = await paintSheet(sheets[i]);
                status.textContent = 'Convertendo página ' + (i + 1) + ' com perfil ICC e verde ajustado…';
                images.push(await compress(toCMYK(rgba)));
            }
            status.textContent = 'Finalizando PDF para gráfica…';
            var file = makePdf(images[0], images[1]);
            var url = URL.createObjectURL(file);
            var link = document.createElement('a');
            link.href = url;
            link.download = safeFilename();
            document.body.appendChild(link);
            link.click(); link.remove();
            setTimeout(function () { URL.revokeObjectURL(url); }, 60000);
            status.textContent = 'PDF CMYK com perfil ICC e verde institucional corrigido, 600 DPI, sangria 1 mm e marcas de corte. Faça prova de cor na gráfica.';
        } catch (err) {
            status.textContent = 'Não foi possível exportar: ' + (err && err.message ? err.message : 'erro desconhecido');
        } finally {
            button.disabled = false;
            button.textContent = old;
        }
    }

    function setup() {
        var toolbar = document.querySelector('.toolbar');
        if (!toolbar || document.getElementById('smtt-cif-export-cmyk')) { return; }
        var button = document.createElement('button');
        button.type = 'button';
        button.id = 'smtt-cif-export-cmyk';
        button.textContent = 'Exportar PDF para gráfica (CMYK verde + ICC + corte)';
        button.style.marginLeft = '7px';
        button.style.backgroundColor = '#17623b';
        button.style.maxWidth = '100%';
        button.style.whiteSpace = 'normal';
        button.style.textAlign = 'left';
        toolbar.appendChild(button);
        var status = document.createElement('small');
        status.id = 'smtt-cif-export-cmyk-status';
        status.setAttribute('role', 'status');
        status.textContent = 'Frente e verso em CMYK com perfil ICC e verde corrigido. Marcas pretas mostram o corte CR80 de 85,60 × 53,98 mm; a arte ultrapassa esse corte em 1 mm. A margem branca externa contém somente as marcas e não faz parte da carteira.';
        toolbar.appendChild(status);
        button.addEventListener('click', function () { exportPdf(button, status); });
    }
    if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', setup); }
    else { setup(); }
})();
